def fill_assignment_department(apps, schema_editor):
    """Each branch assignment gets the staff member's department (until now the only one they had)."""
    Assignment = apps.get_model("hospital_setup", "StaffBranchAssignment")
    db = schema_editor.connection.alias
    for a in Assignment.objects.using(db).select_related("staff").filter(department__isnull=True, staff__department__isnull=False):
        a.department_id = a.staff.department_id
        a.save(using=db, update_fields=["department"])


